// Um item por conversa. O prompt carrega SO o que o modelo precisa julgar.
// `sentido` fica de fora de proposito: ele e determinístico (quem mandou a ultima
// mensagem) e ja veio resolvido da Edge Function. Quanto menos o LLM decide, menos
// ele tem como errar.
const conversas = $input.first().json?.conversas ?? [];
const saida = [];

for (const c of conversas) {
  const transcricao = c.mensagens
    .map((m) => `${m.de === 'cliente' ? 'CLIENTE' : 'NOS'}: ${m.texto}`)
    .join('\n');

  const prompt = [
    'Voce registra pontos de contato no CRM da Mont Distribuidora, que vende pao de',
    'queijo artesanal por WhatsApp. Leia a conversa e produza o registro que um bom',
    'vendedor escreveria DEPOIS de encerrar o atendimento.',
    '',
    `Cliente: ${c.nome ?? 'sem nome'}`,
    '',
    'CONVERSA:',
    transcricao,
    '',
    'Regras:',
    '- observacao: no maximo 2 frases, em portugues, objetiva. Diga o que foi tratado e',
    '  como ficou. Nada de floreio, nada de repetir a conversa inteira.',
    '- tipo: use "feedback" apenas quando o cliente opina sobre produto/atendimento',
    '  (elogio ou reclamacao). Caso contrario, "ponto_contato".',
    '- resultado: descreve a RESPOSTA DO CLIENTE.',
    '    "aceitou"  = fechou pedido ou concordou com a oferta;',
    '    "recusou"  = disse claramente que NAO quer. Use com parcimonia: isso congela',
    '                 o cliente por 30 dias. "agora nao" ou "depois eu vejo" NAO e recusa;',
    '    "respondeu"= interagiu sem fechar nem recusar;',
    '    "nenhum"   = so nos falamos, ou nao da pra dizer.'
  ].join('\n');

  saida.push({ json: { contato_id: c.contato_id, telefone_wa: c.telefone_wa, nome: c.nome, sentido: c.sentido, message_ids: c.message_ids, prompt } });
}

return saida;

// Junta o veredito do LLM com o que ja era determinístico. Se o Gemini falhar ou
// devolver algo ilegivel, a conversa e PULADA — nao vai lixo pra timeline, e ela
// volta na proxima rodada porque nunca saiu da fila.
const saida = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  const base = $('Montar prompt por conversa').all()[i]?.json;
  if (!base) continue;

  const texto = entradas[i].json?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!texto) continue;

  let v;
  try { v = JSON.parse(texto); } catch { continue; }
  if (!v || typeof v.observacao !== 'string' || !v.observacao.trim()) continue;

  saida.push({ json: {
    acao: 'registrar',
    telefone_wa: base.telefone_wa,
    message_ids: base.message_ids,
    analise: {
      tipo: v.tipo,
      sentido: base.sentido,               // determinístico, nao do LLM
      resultado: v.resultado === 'nenhum' ? null : v.resultado,
      observacao: v.observacao.trim(),
    },
  } });
}

return saida;
